  1→#!/usr/bin/env bun
  2→/**
  3→ * Voice Server - Personal AI Voice notification server using ElevenLabs TTS
  4→ *
  5→ * Architecture: Pure pass-through. All voice config comes from settings.json.
  6→ * The server has zero hardcoded voice parameters.
  7→ *
  8→ * Config resolution (3-tier):
  9→ *   1. Caller sends voice_settings in request body → use directly (pass-through)
 10→ *   2. Caller sends voice_id → look up in settings.json daidentity.voices → use those settings
 11→ *   3. Neither → use settings.json daidentity.voices.main as default
 12→ *
 13→ * Pronunciation preprocessing: loads pronunciations.json and applies
 14→ * word-boundary replacements before sending text to ElevenLabs TTS.
 15→ */
 16→
 17→import { serve } from "bun";
 18→import { spawn } from "child_process";
 19→import { homedir } from "os";
 20→import { join } from "path";
 21→import { existsSync, readFileSync } from "fs";
 22→
 23→// Load .env from user home directory
 24→const envPath = join(homedir(), '.env');
 25→if (existsSync(envPath)) {
 26→  const envContent = await Bun.file(envPath).text();
 27→  envContent.split('\n').forEach(line => {
 28→    const [key, value] = line.split('=');
 29→    if (key && value && !key.startsWith('#')) {
 30→      process.env[key.trim()] = value.trim();
 31→    }
 32→  });
 33→}
 34→
 35→const PORT = parseInt(process.env.PORT || "8888");
 36→const ELEVENLABS_API_KEY = process.env.ELEVENLABS_API_KEY;
 37→
 38→if (!ELEVENLABS_API_KEY) {
 39→  console.error('⚠️  ELEVENLABS_API_KEY not found in ~/.env');
 40→  console.error('Add: ELEVENLABS_API_KEY=your_key_here');
 41→}
 42→
 43→// ==========================================================================
 44→// Pronunciation System
 45→// ==========================================================================
 46→
 47→interface PronunciationEntry {
 48→  term: string;
 49→  phonetic: string;
 50→  note?: string;
 51→}
 52→
 53→interface PronunciationConfig {
 54→  replacements: PronunciationEntry[];
 55→}
 56→
 57→// Compiled pronunciation rules (loaded once at startup)
 58→interface CompiledRule {
 59→  regex: RegExp;
 60→  phonetic: string;
 61→}
 62→
 63→let pronunciationRules: CompiledRule[] = [];
 64→
 65→// Load and compile pronunciation rules from pronunciations.json
 66→function loadPronunciations(): void {
 67→  const pronPath = join(import.meta.dir, 'pronunciations.json');
 68→  try {
 69→    if (!existsSync(pronPath)) {
 70→      console.warn('⚠️  No pronunciations.json found — TTS will use default pronunciations');
 71→      return;
 72→    }
 73→    const content = readFileSync(pronPath, 'utf-8');
 74→    const config: PronunciationConfig = JSON.parse(content);
 75→
 76→    pronunciationRules = config.replacements.map(entry => ({
 77→      // Word-boundary matching: \b ensures "Kai" matches but "Kaiser" doesn't
 78→      regex: new RegExp(`\\b${escapeRegex(entry.term)}\\b`, 'g'),
 79→      phonetic: entry.phonetic,
 80→    }));
 81→
 82→    console.log(`📖 Loaded ${pronunciationRules.length} pronunciation rules`);
 83→    for (const entry of config.replacements) {
 84→      console.log(`   ${entry.term} → ${entry.phonetic} (${entry.note || ''})`);
 85→    }
 86→  } catch (error) {
 87→    console.error('⚠️  Failed to load pronunciations.json:', error);
 88→  }
 89→}
 90→
 91→// Escape special regex characters in a literal string
 92→function escapeRegex(str: string): string {
 93→  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
 94→}
 95→
 96→// Apply all pronunciation replacements to text before TTS
 97→function applyPronunciations(text: string): string {
 98→  let result = text;
 99→  for (const rule of pronunciationRules) {
100→    result = result.replace(rule.regex, rule.phonetic);
101→  }
102→  return result;
103→}
104→
105→// Load pronunciations at startup
106→loadPronunciations();
107→
108→// ==========================================================================
109→// Voice Configuration — Single Source of Truth: settings.json
110→// ==========================================================================
111→
112→// ElevenLabs voice_settings fields (sent to their API)
113→interface ElevenLabsVoiceSettings {
114→  stability: number;
115→  similarity_boost: number;
116→  style?: number;
117→  speed?: number;
118→  use_speaker_boost?: boolean;
119→}
120→
121→// A voice entry from settings.json daidentity.voices.*
122→interface VoiceEntry {
123→  voiceId: string;
124→  voiceName?: string;
125→  stability: number;
126→  similarity_boost: number;
127→  style: number;
128→  speed: number;
129→  use_speaker_boost: boolean;
130→  volume: number;
131→}
132→
133→// Loaded config from settings.json
134→interface LoadedVoiceConfig {
135→  defaultVoiceId: string;
136→  voices: Record<string, VoiceEntry>;     // keyed by name ("main", "algorithm")
137→  voicesByVoiceId: Record<string, VoiceEntry>;  // keyed by voiceId for lookup
138→}
139→
140→// Last-resort defaults if settings.json is entirely missing or unparseable
141→const FALLBACK_VOICE_SETTINGS: ElevenLabsVoiceSettings = {
142→  stability: 0.5,
143→  similarity_boost: 0.75,
144→  style: 0.0,
145→  speed: 1.0,
146→  use_speaker_boost: true,
147→};
148→const FALLBACK_VOLUME = 1.0;
149→
150→// Load voice configuration from settings.json (cached at startup)
151→function loadVoiceConfig(): LoadedVoiceConfig {
152→  const settingsPath = join(homedir(), '.claude', 'settings.json');
153→
154→  try {
155→    if (!existsSync(settingsPath)) {
156→      console.warn('⚠️  settings.json not found — using fallback voice defaults');
157→      return { defaultVoiceId: '', voices: {}, voicesByVoiceId: {} };
158→    }
159→
160→    const content = readFileSync(settingsPath, 'utf-8');
161→    const settings = JSON.parse(content);
162→    const daidentity = settings.daidentity || {};
163→    const voicesSection = daidentity.voices || {};
164→
165→    // Build lookup maps
166→    const voices: Record<string, VoiceEntry> = {};
167→    const voicesByVoiceId: Record<string, VoiceEntry> = {};
168→
169→    for (const [name, config] of Object.entries(voicesSection)) {
170→      const entry = config as any;
171→      if (entry.voiceId) {
172→        const voiceEntry: VoiceEntry = {
173→          voiceId: entry.voiceId,
174→          voiceName: entry.voiceName,
175→          stability: entry.stability ?? 0.5,
176→          similarity_boost: entry.similarity_boost ?? 0.75,
177→          style: entry.style ?? 0.0,
178→          speed: entry.speed ?? 1.0,
179→          use_speaker_boost: entry.use_speaker_boost ?? true,
180→          volume: entry.volume ?? 1.0,
181→        };
182→        voices[name] = voiceEntry;
183→        voicesByVoiceId[entry.voiceId] = voiceEntry;
184→      }
185→    }
186→
187→    // Default voice ID from settings
188→    const defaultVoiceId = voices.main?.voiceId || daidentity.mainDAVoiceID || '';
189→
190→    const voiceNames = Object.keys(voices);
191→    console.log(`✅ Loaded ${voiceNames.length} voice config(s) from settings.json: ${voiceNames.join(', ')}`);
192→    for (const [name, entry] of Object.entries(voices)) {
193→      console.log(`   ${name}: ${entry.voiceName || entry.voiceId} (speed: ${entry.speed}, stability: ${entry.stability})`);
194→    }
195→
196→    return { defaultVoiceId, voices, voicesByVoiceId };
197→  } catch (error) {
198→    console.error('⚠️  Failed to load settings.json voice config:', error);
199→    return { defaultVoiceId: '', voices: {}, voicesByVoiceId: {} };
200→  }
201→}
202→
203→// Load config at startup
204→const voiceConfig = loadVoiceConfig();
205→const DEFAULT_VOICE_ID = voiceConfig.defaultVoiceId || process.env.ELEVENLABS_VOICE_ID || "{YOUR_ELEVENLABS_VOICE_ID}";
206→
207→// Look up a voice entry by voice ID
208→function lookupVoiceByVoiceId(voiceId: string): VoiceEntry | null {
209→  return voiceConfig.voicesByVoiceId[voiceId] || null;
210→}
211→
212→// Get ElevenLabs voice settings for a voice entry
213→function voiceEntryToSettings(entry: VoiceEntry): ElevenLabsVoiceSettings {
214→  return {
215→    stability: entry.stability,
216→    similarity_boost: entry.similarity_boost,
217→    style: entry.style,
218→    speed: entry.speed,
219→    use_speaker_boost: entry.use_speaker_boost,
220→  };
221→}
222→
223→// Emotional markers for dynamic voice adjustment (overlay-only — modifies stability + similarity_boost)
224→interface EmotionalOverlay {
225→  stability: number;
226→  similarity_boost: number;
227→}
228→
229→// 13 Emotional Presets - Expanded Prosody System
230→// These OVERLAY onto resolved voice settings, not replace them
231→const EMOTIONAL_PRESETS: Record<string, EmotionalOverlay> = {
232→  // High Energy / Positive
233→  'excited': { stability: 0.7, similarity_boost: 0.9 },
234→  'celebration': { stability: 0.65, similarity_boost: 0.85 },
235→  'insight': { stability: 0.55, similarity_boost: 0.8 },
236→  'creative': { stability: 0.5, similarity_boost: 0.75 },
237→
238→  // Success / Achievement
239→  'success': { stability: 0.6, similarity_boost: 0.8 },
240→  'progress': { stability: 0.55, similarity_boost: 0.75 },
241→
242→  // Analysis / Investigation
243→  'investigating': { stability: 0.6, similarity_boost: 0.85 },
244→  'debugging': { stability: 0.55, similarity_boost: 0.8 },
245→  'learning': { stability: 0.5, similarity_boost: 0.75 },
246→
247→  // Thoughtful / Careful
248→  'pondering': { stability: 0.65, similarity_boost: 0.8 },
249→  'focused': { stability: 0.7, similarity_boost: 0.85 },
250→  'caution': { stability: 0.4, similarity_boost: 0.6 },
251→
252→  // Urgent / Critical
253→  'urgent': { stability: 0.3, similarity_boost: 0.9 },
254→};
