256→// Escape special characters for AppleScript
257→function escapeForAppleScript(input: string): string {
258→  return input.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
259→}
260→
261→// Extract emotional marker from message
262→function extractEmotionalMarker(message: string): { cleaned: string; emotion?: string } {
263→  const emojiToEmotion: Record<string, string> = {
264→    '\u{1F4A5}': 'excited',
265→    '\u{1F389}': 'celebration',
266→    '\u{1F4A1}': 'insight',
267→    '\u{1F3A8}': 'creative',
268→    '\u{2728}': 'success',
269→    '\u{1F4C8}': 'progress',
270→    '\u{1F50D}': 'investigating',
271→    '\u{1F41B}': 'debugging',
272→    '\u{1F4DA}': 'learning',
273→    '\u{1F914}': 'pondering',
274→    '\u{1F3AF}': 'focused',
275→    '\u{26A0}\u{FE0F}': 'caution',
276→    '\u{1F6A8}': 'urgent'
277→  };
278→
279→  const emotionMatch = message.match(/\[(\u{1F4A5}|\u{1F389}|\u{1F4A1}|\u{1F3A8}|\u{2728}|\u{1F4C8}|\u{1F50D}|\u{1F41B}|\u{1F4DA}|\u{1F914}|\u{1F3AF}|\u{26A0}\u{FE0F}|\u{1F6A8})\s+(\w+)\]/u);
280→  if (emotionMatch) {
281→    const emoji = emotionMatch[1];
282→    const emotionName = emotionMatch[2].toLowerCase();
283→
284→    if (emojiToEmotion[emoji] === emotionName) {
285→      return {
286→        cleaned: message.replace(emotionMatch[0], '').trim(),
287→        emotion: emotionName
288→      };
289→    }
290→  }
291→
292→  return { cleaned: message };
293→}
294→
295→// Sanitize input for TTS and notifications
296→function sanitizeForSpeech(input: string): string {
297→  const cleaned = input
298→    .replace(/<script/gi, '')
299→    .replace(/\.\.\//g, '')
300→    .replace(/[;&|><`$\\]/g, '')
301→    .replace(/\*\*([^*]+)\*\*/g, '$1')
302→    .replace(/\*([^*]+)\*/g, '$1')
303→    .replace(/`([^`]+)`/g, '$1')
304→    .replace(/#{1,6}\s+/g, '')
305→    .trim()
306→    .substring(0, 500);
307→
308→  return cleaned;
309→}
310→
311→// Validate user input
312→function validateInput(input: any): { valid: boolean; error?: string; sanitized?: string } {
313→  if (!input || typeof input !== 'string') {
314→    return { valid: false, error: 'Invalid input type' };
315→  }
316→
317→  if (input.length > 500) {
318→    return { valid: false, error: 'Message too long (max 500 characters)' };
319→  }
320→
321→  const sanitized = sanitizeForSpeech(input);
322→
323→  if (!sanitized || sanitized.length === 0) {
324→    return { valid: false, error: 'Message contains no valid content after sanitization' };
325→  }
326→
327→  return { valid: true, sanitized };
328→}
329→
330→// Generate speech using ElevenLabs API — pure pass-through of voice_settings
331→async function generateSpeech(
332→  text: string,
333→  voiceId: string,
334→  voiceSettings: ElevenLabsVoiceSettings
335→): Promise<ArrayBuffer> {
336→  if (!ELEVENLABS_API_KEY) {
337→    throw new Error('ElevenLabs API key not configured');
338→  }
339→
340→  // Apply pronunciation replacements before sending to TTS
341→  const pronouncedText = applyPronunciations(text);
342→  if (pronouncedText !== text) {
343→    console.log(`📖 Pronunciation: "${text}" → "${pronouncedText}"`);
344→  }
345→
346→  const url = `https://api.elevenlabs.io/v1/text-to-speech/${voiceId}`;
347→
348→  const response = await fetch(url, {
349→    method: 'POST',
350→    headers: {
351→      'Accept': 'audio/mpeg',
352→      'Content-Type': 'application/json',
353→      'xi-api-key': ELEVENLABS_API_KEY,
354→    },
355→    body: JSON.stringify({
356→      text: pronouncedText,
357→      model_id: 'eleven_turbo_v2_5',
358→      voice_settings: voiceSettings,
359→    }),
360→  });
361→
362→  if (!response.ok) {
363→    const errorText = await response.text();
364→    throw new Error(`ElevenLabs API error: ${response.status} - ${errorText}`);
365→  }
366→
367→  return await response.arrayBuffer();
368→}
369→
370→// Play audio using afplay (macOS)
371→async function playAudio(audioBuffer: ArrayBuffer, volume: number = FALLBACK_VOLUME): Promise<void> {
372→  const tempFile = `/tmp/voice-${Date.now()}.mp3`;
373→
374→  await Bun.write(tempFile, audioBuffer);
375→
376→  return new Promise((resolve, reject) => {
377→    const proc = spawn('/usr/bin/afplay', ['-v', volume.toString(), tempFile]);
378→
379→    proc.on('error', (error) => {
380→      console.error('Error playing audio:', error);
381→      reject(error);
382→    });
383→
384→    proc.on('exit', (code) => {
385→      spawn('/bin/rm', [tempFile]);
386→      if (code === 0) {
387→        resolve();
388→      } else {
389→        reject(new Error(`afplay exited with code ${code}`));
390→      }
391→    });
392→  });
393→}
394→
395→// Spawn a process safely
396→function spawnSafe(command: string, args: string[]): Promise<void> {
397→  return new Promise((resolve, reject) => {
398→    const proc = spawn(command, args);
399→
400→    proc.on('error', (error) => {
401→      console.error(`Error spawning ${command}:`, error);
402→      reject(error);
403→    });
404→
405→    proc.on('exit', (code) => {
406→      if (code === 0) {
407→        resolve();
408→      } else {
409→        reject(new Error(`${command} exited with code ${code}`));
410→      }
411→    });
412→  });
413→}
