415→// ==========================================================================
416→// Core: Send notification with 3-tier voice settings resolution
417→// ==========================================================================
418→
419→/**
420→ * Send macOS notification with voice.
421→ *
422→ * Voice settings resolution (3-tier):
423→ *   1. callerVoiceSettings provided → use directly (pass-through)
424→ *   2. voiceId provided → look up in settings.json → use those settings
425→ *   3. Neither → use settings.json voices.main defaults
426→ *
427→ * Emotional presets overlay stability + similarity_boost onto resolved settings.
428→ * Volume is resolved separately: caller → voice entry → main → 1.0 fallback.
429→ */
430→async function sendNotification(
431→  title: string,
432→  message: string,
433→  voiceEnabled = true,
434→  voiceId: string | null = null,
435→  callerVoiceSettings?: Partial<ElevenLabsVoiceSettings> | null,
436→  callerVolume?: number | null,
437→) {
438→  const titleValidation = validateInput(title);
439→  const messageValidation = validateInput(message);
440→
441→  if (!titleValidation.valid) {
442→    throw new Error(`Invalid title: ${titleValidation.error}`);
443→  }
444→
445→  if (!messageValidation.valid) {
446→    throw new Error(`Invalid message: ${messageValidation.error}`);
447→  }
448→
449→  const safeTitle = titleValidation.sanitized!;
450→  let safeMessage = messageValidation.sanitized!;
451→
452→  const { cleaned, emotion } = extractEmotionalMarker(safeMessage);
453→  safeMessage = cleaned;
454→
455→  // Generate and play voice using ElevenLabs
456→  if (voiceEnabled && ELEVENLABS_API_KEY) {
457→    try {
458→      const voice = voiceId || DEFAULT_VOICE_ID;
459→
460→      // 3-tier voice settings resolution
461→      let resolvedSettings: ElevenLabsVoiceSettings;
462→      let resolvedVolume: number;
463→
464→      if (callerVoiceSettings && Object.keys(callerVoiceSettings).length > 0) {
465→        // Tier 1: Caller provided explicit voice_settings → pass through
466→        resolvedSettings = {
467→          stability: callerVoiceSettings.stability ?? FALLBACK_VOICE_SETTINGS.stability,
468→          similarity_boost: callerVoiceSettings.similarity_boost ?? FALLBACK_VOICE_SETTINGS.similarity_boost,
469→          style: callerVoiceSettings.style ?? FALLBACK_VOICE_SETTINGS.style,
470→          speed: callerVoiceSettings.speed ?? FALLBACK_VOICE_SETTINGS.speed,
471→          use_speaker_boost: callerVoiceSettings.use_speaker_boost ?? FALLBACK_VOICE_SETTINGS.use_speaker_boost,
472→        };
473→        resolvedVolume = callerVolume ?? FALLBACK_VOLUME;
474→        console.log(`🔗 Voice settings: pass-through from caller`);
475→      } else {
476→        // Tier 2/3: Look up by voiceId, fall back to main
477→        const voiceEntry = lookupVoiceByVoiceId(voice) || voiceConfig.voices.main;
478→        if (voiceEntry) {
479→          resolvedSettings = voiceEntryToSettings(voiceEntry);
480→          resolvedVolume = callerVolume ?? voiceEntry.volume ?? FALLBACK_VOLUME;
481→          console.log(`📋 Voice settings: from settings.json (${voiceEntry.voiceName || voice})`);
482→        } else {
483→          resolvedSettings = { ...FALLBACK_VOICE_SETTINGS };
484→          resolvedVolume = callerVolume ?? FALLBACK_VOLUME;
485→          console.log(`⚠️  Voice settings: fallback defaults (no config found for ${voice})`);
486→        }
487→      }
488→
489→      // Emotional preset overlay — modifies stability + similarity_boost only
490→      if (emotion && EMOTIONAL_PRESETS[emotion]) {
491→        resolvedSettings = {
492→          ...resolvedSettings,
493→          stability: EMOTIONAL_PRESETS[emotion].stability,
494→          similarity_boost: EMOTIONAL_PRESETS[emotion].similarity_boost,
495→        };
496→        console.log(`🎭 Emotion overlay: ${emotion}`);
497→      }
498→
499→      console.log(`🎙️  Generating speech (voice: ${voice}, speed: ${resolvedSettings.speed}, stability: ${resolvedSettings.stability}, boost: ${resolvedSettings.similarity_boost}, style: ${resolvedSettings.style}, volume: ${resolvedVolume})`);
500→
501→      const audioBuffer = await generateSpeech(safeMessage, voice, resolvedSettings);
502→      await playAudio(audioBuffer, resolvedVolume);
503→    } catch (error) {
504→      console.error("Failed to generate/play speech:", error);
505→    }
506→  }
507→
508→  // Display macOS notification
509→  try {
510→    const escapedTitle = escapeForAppleScript(safeTitle);
511→    const escapedMessage = escapeForAppleScript(safeMessage);
512→    const script = `display notification "${escapedMessage}" with title "${escapedTitle}" sound name ""`;
513→    await spawnSafe('/usr/bin/osascript', ['-e', script]);
514→  } catch (error) {
515→    console.error("Notification display error:", error);
516→  }
517→}
