519→// Rate limiting
520→const requestCounts = new Map<string, { count: number; resetTime: number }>();
521→const RATE_LIMIT = 10;
522→const RATE_WINDOW = 60000;
523→
524→function checkRateLimit(ip: string): boolean {
525→  const now = Date.now();
526→  const record = requestCounts.get(ip);
527→
528→  if (!record || now > record.resetTime) {
529→    requestCounts.set(ip, { count: 1, resetTime: now + RATE_WINDOW });
530→    return true;
531→  }
532→
533→  if (record.count >= RATE_LIMIT) {
534→    return false;
535→  }
536→
537→  record.count++;
538→  return true;
539→}
