541→// Start HTTP server
542→const server = serve({
543→  port: PORT,
544→  async fetch(req) {
545→    const url = new URL(req.url);
546→
547→    const clientIp = req.headers.get('x-forwarded-for') || 'localhost';
548→
549→    const corsHeaders = {
550→      "Access-Control-Allow-Origin": "http://localhost",
551→      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
552→      "Access-Control-Allow-Headers": "Content-Type"
553→    };
554→
555→    if (req.method === "OPTIONS") {
556→      return new Response(null, { headers: corsHeaders, status: 204 });
557→    }
558→
559→    if (!checkRateLimit(clientIp)) {
560→      return new Response(
561→        JSON.stringify({ status: "error", message: "Rate limit exceeded" }),
562→        {
563→          headers: { ...corsHeaders, "Content-Type": "application/json" },
564→          status: 429
565→        }
566→      );
567→    }
568→
569→    if (url.pathname === "/notify" && req.method === "POST") {
570→      try {
571→        const data = await req.json();
572→        const title = data.title || "PAI Notification";
573→        const message = data.message || "Task completed";
574→        const voiceEnabled = data.voice_enabled !== false;
575→        const voiceId = data.voice_id || data.voice_name || null;
576→        const voiceSettings = data.voice_settings || null;
577→        const volume = data.volume ?? null;
578→
579→        if (voiceId && typeof voiceId !== 'string') {
580→          throw new Error('Invalid voice_id');
581→        }
582→
583→        console.log(`📨 Notification: "${title}" - "${message}" (voice: ${voiceEnabled}, voiceId: ${voiceId || DEFAULT_VOICE_ID})`);
584→
585→        await sendNotification(title, message, voiceEnabled, voiceId, voiceSettings, volume);
586→
587→        return new Response(
588→          JSON.stringify({ status: "success", message: "Notification sent" }),
589→          {
590→            headers: { ...corsHeaders, "Content-Type": "application/json" },
591→            status: 200
592→          }
593→        );
594→      } catch (error: any) {
595→        console.error("Notification error:", error);
596→        return new Response(
597→          JSON.stringify({ status: "error", message: error.message || "Internal server error" }),
598→          {
599→            headers: { ...corsHeaders, "Content-Type": "application/json" },
600→            status: error.message?.includes('Invalid') ? 400 : 500
601→          }
602→        );
603→      }
604→    }
605→
606→    // /notify/personality — compatibility shim for callers using the old Qwen3-TTS endpoint
607→    // Personality fields are Qwen3-specific; for ElevenLabs, we just speak with default voice
608→    if (url.pathname === "/notify/personality" && req.method === "POST") {
609→      try {
610→        const data = await req.json();
611→        const message = data.message || "Notification";
